UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites arithmétiques et géométriques","subtitle_fr":"Raison additive ou multiplicative, terme général, sommes.","sections":[{"kind":"concept","title_fr":"Suites arithmétiques","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une suite est **arithmétique** si l''on passe d''un terme au suivant en **ajoutant** toujours le même nombre $r$ (la **raison**)."},{"kind":"formula","latex":"u_{n+1} = u_n + r \\qquad u_n = u_0 + n r","caption_fr":"Définitions par récurrence et explicite."},{"kind":"formula","latex":"S_n = (n+1) \\cdot \\frac{u_0 + u_n}{2}","caption_fr":"Somme de Gauss : (nombre de termes) × (premier + dernier) / 2."},{"kind":"example","title_fr":"Identifier et sommer","problem_fr":"Calcule $1 + 2 + 3 + \\dots + 100$.","steps_fr":["Suite arithmétique $u_n = n+1$ avec $u_0=1$, $u_{99}=100$, raison $r=1$.","100 termes : $S = 100 \\times (1+100)/2 = 5050$."],"answer_fr":"$S = 5050$."}]},{"kind":"concept","title_fr":"Suites géométriques","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une suite est **géométrique** si l''on passe d''un terme au suivant en **multipliant** par un même nombre $q$ (la **raison**)."},{"kind":"formula","latex":"u_{n+1} = u_n \\cdot q \\qquad u_n = u_0 \\cdot q^n","caption_fr":"Définitions."},{"kind":"formula","latex":"S_n = u_0 \\cdot \\frac{1 - q^{n+1}}{1 - q} \\quad (q \\ne 1)","caption_fr":"Somme géométrique."},{"kind":"callout","tone":"insight","title_fr":"Comportement à l''infini","body_fr":"Si $|q| < 1$ : $u_n \\to 0$. Si $q > 1$ : $u_n \\to +\\infty$. Si $q \\le -1$ : oscille (pas de limite)."},{"kind":"checkpoint","title_fr":"Suites arithmétiques et géométriques","questions":[{"stem_fr":"Raison de la suite $5, 9, 13, 17, \\dots$ ?","choices_fr":["3","4","5","9"],"correct_index":1,"explanation_fr":"$9 - 5 = 4$ (différence constante)."},{"stem_fr":"$u_0 = 2$, $q = 3$. Que vaut $u_3$ ?","choices_fr":["27","54","81","162"],"correct_index":1,"explanation_fr":"$u_3 = 2 \\cdot 3^3 = 54$."},{"stem_fr":"Somme $1+2+\\dots+50$ ?","choices_fr":["1225","1275","2550","2500"],"correct_index":1,"explanation_fr":"$50 \\times 51/2 = 1275$."}]}]}]}'::jsonb WHERE code = 'pc_arithmetic_geom_seq';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Convergence des suites","subtitle_fr":"Limite, théorème des gendarmes, monotonie + bornes.","sections":[{"kind":"concept","title_fr":"Définition de la limite","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une suite $(u_n)$ **converge vers** $\\ell$ si $u_n$ se rapproche autant qu''on veut de $\\ell$ pour $n$ grand. Si la limite est $\\pm\\infty$ ou n''existe pas, la suite **diverge**."},{"kind":"formula","latex":"\\lim_{n \\to +\\infty} \\frac{1}{n^\\alpha} = 0 \\quad (\\alpha > 0)","caption_fr":"Suite de référence : $1/n, 1/n^2, 1/\\sqrt n$ tendent vers 0."},{"kind":"formula","latex":"\\lim q^n = 0 \\text{ si } |q| < 1, \\quad = +\\infty \\text{ si } q > 1","caption_fr":"Suite géométrique."}]},{"kind":"concept","title_fr":"Théorèmes utiles","eyebrow_fr":"THÉORÈMES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Théorème des gendarmes** : si $a_n \\le u_n \\le b_n$ avec $a_n, b_n \\to \\ell$, alors $u_n \\to \\ell$."},{"kind":"paragraph","md":"**Théorème de la limite monotone** : toute suite croissante majorée (ou décroissante minorée) **converge**."},{"kind":"example","title_fr":"Gendarmes","problem_fr":"Calcule $\\lim \\dfrac{\\sin n}{n}$.","steps_fr":["$-1 \\le \\sin n \\le 1$, donc $-1/n \\le \\sin n / n \\le 1/n$.","Les bornes tendent vers 0 → par gendarmes, limite = 0."],"answer_fr":"0."},{"kind":"checkpoint","title_fr":"Convergence","questions":[{"stem_fr":"$\\lim_{n \\to \\infty} 1/n^2$ vaut :","choices_fr":["0","1","∞","n''existe pas"],"correct_index":0,"explanation_fr":"$1/n^\\alpha \\to 0$ pour tout $\\alpha > 0$."},{"stem_fr":"$\\lim (1/2)^n$ vaut :","choices_fr":["0","1/2","1","∞"],"correct_index":0,"explanation_fr":"$|q| < 1$ → $q^n \\to 0$."},{"stem_fr":"Une suite croissante majorée :","choices_fr":["diverge","oscille","converge","tend vers 0"],"correct_index":2,"explanation_fr":"Théorème de la limite monotone."}]}]}]}'::jsonb WHERE code = 'pc_seq_convergence';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites récurrentes","subtitle_fr":"Point fixe, suites arithmético-géométriques.","sections":[{"kind":"concept","title_fr":"Récurrence $u_{n+1} = f(u_n)$","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Une suite **récurrente** est définie par $u_0$ et une relation $u_{n+1} = f(u_n)$. Le calcul donne $u_0, u_1, u_2, \\dots$ de proche en proche."},{"kind":"paragraph","md":"Un **point fixe** $\\ell$ vérifie $\\ell = f(\\ell)$. Si la suite converge, sa limite est un point fixe — mais l''existence d''un point fixe ne suffit pas à prouver la convergence."},{"kind":"callout","tone":"warning","title_fr":"Stratégie standard","body_fr":"Pour étudier la convergence : (1) trouver le(s) point(s) fixe(s), (2) montrer monotonie + bornes par récurrence, (3) conclure par le théorème de la limite monotone."}]},{"kind":"concept","title_fr":"Arithmético-géométrique","eyebrow_fr":"ASTUCE","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Pour $u_{n+1} = a u_n + b$ avec $a \\ne 1$ : trouver le point fixe $\\ell = b/(1-a)$, puis poser $v_n = u_n - \\ell$. Alors $(v_n)$ est **géométrique** de raison $a$."},{"kind":"example","title_fr":"Méthode du point fixe","problem_fr":"Soit $u_0 = 0$ et $u_{n+1} = 3 u_n - 4$. Donner $u_n$ explicite.","steps_fr":["Point fixe : $\\ell = 3\\ell - 4 \\Rightarrow \\ell = 2$.","Poser $v_n = u_n - 2$. Alors $v_{n+1} = 3 v_n$, géométrique de raison 3.","$v_0 = -2$ → $v_n = -2 \\cdot 3^n$ → $u_n = 2 - 2 \\cdot 3^n$."],"answer_fr":"$u_n = 2 - 2 \\cdot 3^n$."},{"kind":"checkpoint","title_fr":"Suites récurrentes","questions":[{"stem_fr":"Point fixe de $f(x) = (x+6)/2$ :","choices_fr":["2","4","6","8"],"correct_index":2,"explanation_fr":"$\\ell = (\\ell + 6)/2 \\iff \\ell = 6$."},{"stem_fr":"Pour $u_{n+1} = 2 u_n + 3$, $\\ell = ?$","choices_fr":["-3","-1","0","3"],"correct_index":0,"explanation_fr":"$\\ell = 2\\ell + 3 \\iff \\ell = -3$."},{"stem_fr":"Si $u_n$ croissante et majorée alors :","choices_fr":["diverge","converge","oscille","rien"],"correct_index":1,"explanation_fr":"Théorème de la limite monotone."}]}]}]}'::jsonb WHERE code = 'pc_seq_recursive';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Calcul de limites","subtitle_fr":"Substitution, factorisation, quantité conjuguée, croissances comparées.","sections":[{"kind":"concept","title_fr":"Méthodes de calcul","eyebrow_fr":"MÉTHODES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**1. Substitution directe** : si $f$ est continue en $a$, alors $\\lim_{x \\to a} f(x) = f(a)$. À tenter en premier."},{"kind":"paragraph","md":"**2. Forme $0/0$ avec polynômes** : factoriser par $(x - a)$ et simplifier."},{"kind":"paragraph","md":"**3. Forme $\\infty - \\infty$ avec racines** : multiplier par la quantité conjuguée."},{"kind":"paragraph","md":"**4. Quotient de polynômes à l''infini** : limite = rapport des coefficients dominants si même degré."},{"kind":"formula","latex":"\\lim_{x \\to +\\infty} \\frac{e^x}{x^n} = +\\infty, \\quad \\lim_{x \\to +\\infty} \\frac{\\ln x}{x^\\alpha} = 0","caption_fr":"**Croissances comparées** : $\\exp \\gg x^n \\gg \\ln$."}]},{"kind":"example_walkthrough","title_fr":"Exemples","eyebrow_fr":"EXEMPLES","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Forme 0/0","problem_fr":"Calcule $\\lim_{x \\to 2} \\dfrac{x^2 - 4}{x - 2}$.","steps_fr":["Forme $0/0$. Factoriser : $x^2 - 4 = (x-2)(x+2)$.","$(x-2)(x+2)/(x-2) = x + 2$ pour $x \\ne 2$.","$\\lim = 2 + 2 = 4$."],"answer_fr":"4."},{"kind":"example","title_fr":"Conjuguée","problem_fr":"Calcule $\\lim_{x \\to 0} \\dfrac{\\sqrt{1+x} - 1}{x}$.","steps_fr":["Multiplier haut et bas par $\\sqrt{1+x} + 1$.","Numérateur devient $(1+x) - 1 = x$. Donc fraction = $1/(\\sqrt{1+x} + 1)$.","Limite en 0 : $1/(1+1) = 1/2$."],"answer_fr":"1/2."},{"kind":"checkpoint","title_fr":"Limites","questions":[{"stem_fr":"$\\lim_{x \\to 1} \\dfrac{x^2 - 1}{x - 1}$ vaut :","choices_fr":["0","1","2","n''existe pas"],"correct_index":2,"explanation_fr":"$(x-1)(x+1)/(x-1) = x + 1 \\to 2$."},{"stem_fr":"$\\lim_{x \\to +\\infty} e^x/x^{100}$ vaut :","choices_fr":["0","1","∞","100"],"correct_index":2,"explanation_fr":"Croissances comparées : exp l''emporte."},{"stem_fr":"$\\lim_{x \\to +\\infty} (3x^2+x)/(x^2+5)$ :","choices_fr":["0","1","3","∞"],"correct_index":2,"explanation_fr":"Quotient même degré → coeff dominants : 3/1 = 3."}]}]}]}'::jsonb WHERE code = 'pc_limit_calc';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Continuité et théorème des valeurs intermédiaires","subtitle_fr":"Définition, prolongement, TVI, dichotomie.","sections":[{"kind":"concept","title_fr":"Continuité","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une fonction $f$ est **continue en $a$** si $\\lim_{x \\to a} f(x) = f(a)$. Elle est continue **sur $I$** si elle l''est en tout point de $I$."},{"kind":"paragraph","md":"Les fonctions usuelles (polynômes, rationnelles sur leur domaine, $\\sqrt{\\cdot}$, $\\sin$, $\\cos$, $\\exp$, $\\ln$) sont continues sur leur ensemble de définition. Somme/produit/composée de continues = continue."},{"kind":"paragraph","md":"Si $f$ n''est pas définie en $a$ mais $\\lim_{x \\to a} f(x) = \\ell$ existe, on peut **prolonger** $f$ par continuité en posant $\\tilde f(a) = \\ell$."}]},{"kind":"concept","title_fr":"Théorème des valeurs intermédiaires","eyebrow_fr":"TVI","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"f \\text{ continue sur } [a,b], \\, k \\text{ entre } f(a) \\text{ et } f(b) \\Rightarrow \\exists c \\in [a,b] : f(c) = k","caption_fr":"Énoncé."},{"kind":"paragraph","md":"**Corollaire (existence d''une racine)** : si $f$ continue, $f(a) \\cdot f(b) < 0$, alors $\\exists c \\in ]a, b[ : f(c) = 0$."},{"kind":"paragraph","md":"**Unicité** : si en plus $f$ est **strictement monotone** sur $[a, b]$, la racine est unique."},{"kind":"example","title_fr":"Application TVI","problem_fr":"Montrer que $x^3 + 2x - 5 = 0$ a une racine unique dans $[1, 2]$.","steps_fr":["$f(x) = x^3 + 2x - 5$ continue. $f(1) = -2 < 0$, $f(2) = 7 > 0$ → TVI donne une racine.","$f''(x) = 3 x^2 + 2 > 0$ partout → $f$ strictement croissante → racine unique."],"answer_fr":"Racine unique dans $]1, 2[$."},{"kind":"checkpoint","title_fr":"Continuité et TVI","questions":[{"stem_fr":"$f$ continue, $f(0) = -1$, $f(1) = 3$. TVI garantit :","choices_fr":["$f(c) = 0$ pour un $c \\in [0,1]$","$f$ strictement croissante","$f(c) = 5$","rien"],"correct_index":0,"explanation_fr":"0 est entre -1 et 3 → TVI."},{"stem_fr":"Quotient (x²-9)/(x-3) en x=3 :","choices_fr":["continu","discontinu, non prolongeable","prolongeable par 6","prolongeable par 0"],"correct_index":2,"explanation_fr":"Limite = 3+3 = 6 → prolongeable."},{"stem_fr":"Pour montrer l''unicité d''une racine, on utilise :","choices_fr":["TVI seul","monotonie stricte","continuité seule","rien"],"correct_index":1,"explanation_fr":"TVI donne existence, monotonie donne unicité."}]}]}]}'::jsonb WHERE code = 'pc_continuity_tvi';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Règles de dérivation","subtitle_fr":"Linéarité, produit, quotient, composition.","sections":[{"kind":"concept","title_fr":"Définition et dérivées usuelles","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"La **dérivée** de $f$ en $a$ est $f''(a) = \\lim_{h \\to 0} (f(a+h) - f(a))/h$ (taux d''accroissement). C''est la pente de la tangente au point $(a, f(a))$."},{"kind":"formula","latex":"(x^n)'' = n x^{n-1}, \\quad (\\sqrt x)'' = \\frac{1}{2 \\sqrt x}, \\quad (\\sin x)'' = \\cos x","caption_fr":"Dérivées de référence."},{"kind":"formula","latex":"(\\cos x)'' = -\\sin x, \\quad (e^x)'' = e^x, \\quad (\\ln x)'' = \\frac{1}{x}","caption_fr":"Suite."}]},{"kind":"concept","title_fr":"Règles de calcul","eyebrow_fr":"RÈGLES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"(u + v)'' = u'' + v'', \\quad (k u)'' = k u''","caption_fr":"Linéarité."},{"kind":"formula","latex":"(uv)'' = u'' v + u v'', \\quad (u/v)'' = \\frac{u'' v - u v''}{v^2}","caption_fr":"Produit et quotient."},{"kind":"formula","latex":"(f \\circ g)''(x) = f''(g(x)) \\cdot g''(x)","caption_fr":"**Composition** (règle de la chaîne)."},{"kind":"example","title_fr":"Combiner les règles","problem_fr":"Dériver $f(x) = (3x+1)^4$.","steps_fr":["Composition : $u^4$ avec $u = 3x + 1$, donc $u'' = 3$.","$f''(x) = 4 u^3 \\cdot u'' = 4 (3x+1)^3 \\cdot 3 = 12 (3x+1)^3$."],"answer_fr":"$f''(x) = 12(3x+1)^3$."},{"kind":"checkpoint","title_fr":"Dérivation","questions":[{"stem_fr":"Dérivée de $x^3$ :","choices_fr":["$3x$","$3x^2$","$x^2$","$x^4/4$"],"correct_index":1,"explanation_fr":"$(x^n)'' = n x^{n-1}$."},{"stem_fr":"Dérivée de $\\sin x$ :","choices_fr":["$\\sin x$","$\\cos x$","$-\\sin x$","$-\\cos x$"],"correct_index":1,"explanation_fr":"$(\\sin)'' = \\cos$."},{"stem_fr":"Dérivée de $x e^x$ :","choices_fr":["$e^x$","$x e^x$","$(1+x) e^x$","$x^2 e^x$"],"correct_index":2,"explanation_fr":"Produit : $1 \\cdot e^x + x \\cdot e^x = (1+x)e^x$."}]}]}]}'::jsonb WHERE code = 'pc_deriv_rules';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Applications de la dérivation","subtitle_fr":"Variations, extrema, optimisation.","sections":[{"kind":"concept","title_fr":"Sens de variation","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Le signe de la **dérivée** donne le sens de variation : $f'' > 0$ → $f$ strictement croissante ; $f'' < 0$ → strictement décroissante."},{"kind":"paragraph","md":"À un **extremum local** (max ou min) d''une fonction dérivable, la tangente est horizontale → $f''$ s''annule en changeant de signe."},{"kind":"callout","tone":"insight","title_fr":"Recette d''étude","body_fr":"Calculer $f''$, étudier son signe, dresser le tableau de variations, identifier les extrema."}]},{"kind":"concept","title_fr":"Optimisation et inégalités","eyebrow_fr":"APPLICATIONS","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Problème d''optimisation** : on exprime la grandeur à optimiser comme $f(x)$, on dérive, on trouve les points critiques $f''(x) = 0$, on identifie le max/min via le signe de $f''$."},{"kind":"paragraph","md":"**Démontrer une inégalité** $g \\le h$ : étudier la différence $h - g$ et montrer qu''elle est positive (souvent en analysant son extremum)."},{"kind":"example","title_fr":"Boîte à volume maximal","problem_fr":"Une feuille de carton 30×30 cm. On découpe un carré de côté $x$ à chaque coin et on plie. Trouver $x$ qui maximise le volume $V = x(30-2x)^2$.","steps_fr":["$V''(x) = (30-2x)^2 - 4x(30-2x) = (30-2x)(30-6x)$.","Racines : $x = 5$ et $x = 15$ (exclu). Sur $]0, 5[$ : $V'' > 0$ ; au-delà : $V'' < 0$.","Max en $x = 5$, volume $V(5) = 5 \\times 20^2 = 2000\\,\\text{cm}^3$."],"answer_fr":"$x = 5$ cm."},{"kind":"checkpoint","title_fr":"Applications","questions":[{"stem_fr":"À un max local d''une fonction dérivable :","choices_fr":["$f'' = 0$","$f = 0$","$f'' > 0$","$f'''' = 0$"],"correct_index":0,"explanation_fr":"Tangente horizontale → dérivée nulle."},{"stem_fr":"Si $f'' > 0$ sur $I$ alors $f$ est :","choices_fr":["constante","décroissante","croissante","maximale"],"correct_index":2,"explanation_fr":"Dérivée positive ⇒ fonction croissante."},{"stem_fr":"Pour montrer $g \\le h$ on étudie :","choices_fr":["$g+h$","$g \\cdot h$","$h - g$","$g/h$"],"correct_index":2,"explanation_fr":"On montre que la différence est positive."}]}]}]}'::jsonb WHERE code = 'pc_deriv_apps';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Fonction logarithme népérien","subtitle_fr":"Propriétés algébriques, dérivée, équations.","sections":[{"kind":"concept","title_fr":"Définition et propriétés","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"La fonction $\\ln$ est définie sur $]0, +\\infty[$. Elle est l''**inverse** de l''exponentielle : $\\ln(e^x) = x$ et $e^{\\ln x} = x$ (pour $x > 0$)."},{"kind":"formula","latex":"\\ln 1 = 0, \\quad \\ln e = 1, \\quad \\lim_{x \\to 0^+} \\ln x = -\\infty, \\quad \\lim_{x \\to +\\infty} \\ln x = +\\infty","caption_fr":"Valeurs et limites."},{"kind":"formula","latex":"\\ln(ab) = \\ln a + \\ln b, \\quad \\ln(a/b) = \\ln a - \\ln b, \\quad \\ln(a^n) = n \\ln a","caption_fr":"**Propriétés algébriques** fondamentales."}]},{"kind":"concept","title_fr":"Dérivée et équations","eyebrow_fr":"OUTILS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"(\\ln x)'' = \\frac{1}{x}, \\quad (\\ln u)'' = \\frac{u''}{u}","caption_fr":"Dérivée et composition."},{"kind":"paragraph","md":"**Injectivité** : $\\ln u = \\ln v \\iff u = v$ (avec $u, v > 0$). C''est ce qui permet de résoudre les équations logarithmiques."},{"kind":"formula","latex":"\\ln x \\le x - 1 \\quad \\text{(égalité en } x=1\\text{)}","caption_fr":"Inégalité classique, démontrée par étude de $f(x) = x - 1 - \\ln x$."},{"kind":"example","title_fr":"Équation logarithmique","problem_fr":"Résous $\\ln(2x - 1) = \\ln(x + 3)$.","steps_fr":["Domaine : $2x - 1 > 0$ et $x + 3 > 0$ → $x > 1/2$.","Par injectivité : $2x - 1 = x + 3 \\iff x = 4$. $x = 4 > 1/2$ ✓."],"answer_fr":"$S = \\{4\\}$."},{"kind":"checkpoint","title_fr":"Logarithme","questions":[{"stem_fr":"$\\ln(e^3)$ vaut :","choices_fr":["$1/3$","$3$","$e$","$e^3$"],"correct_index":1,"explanation_fr":"$\\ln(e^x) = x$."},{"stem_fr":"Dérivée de $\\ln(x^2 + 1)$ :","choices_fr":["$1/(x^2+1)$","$2x/(x^2+1)$","$\\ln(2x)$","$2x$"],"correct_index":1,"explanation_fr":"$u''/u$ avec $u = x^2+1$, $u'' = 2x$."},{"stem_fr":"$\\ln(2) + \\ln(3) - \\ln(6)$ vaut :","choices_fr":["0","1","$\\ln(6)$","$\\ln(36)$"],"correct_index":0,"explanation_fr":"$\\ln(2 \\cdot 3/6) = \\ln 1 = 0$."}]}]}]}'::jsonb WHERE code = 'pc_ln_function';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Fonction exponentielle","subtitle_fr":"Propriétés, croissances comparées, équations différentielles.","sections":[{"kind":"concept","title_fr":"Propriétés","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"La fonction $\\exp(x) = e^x$ est définie sur $\\mathbb{R}$, à valeurs dans $]0, +\\infty[$. **Strictement croissante**, dérivée égale à elle-même."},{"kind":"formula","latex":"e^0 = 1, \\quad e^1 = e \\approx 2{,}718, \\quad (e^x)'' = e^x, \\quad e^x > 0 \\,\\forall x","caption_fr":"Valeurs et propriété d''auto-dérivation."},{"kind":"formula","latex":"e^a \\cdot e^b = e^{a+b}, \\quad e^a/e^b = e^{a-b}, \\quad (e^a)^n = e^{na}","caption_fr":"Propriétés algébriques."},{"kind":"formula","latex":"\\lim_{x \\to -\\infty} e^x = 0, \\quad \\lim_{x \\to +\\infty} e^x = +\\infty","caption_fr":"Limites."}]},{"kind":"concept","title_fr":"Croissances comparées","eyebrow_fr":"THÉORÈME","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\lim_{x \\to +\\infty} \\frac{e^x}{x^n} = +\\infty, \\quad \\lim_{x \\to +\\infty} x^n e^{-x} = 0","caption_fr":"L''exponentielle l''emporte sur toute puissance."},{"kind":"callout","tone":"insight","title_fr":"Hiérarchie","body_fr":"À l''infini : $\\exp \\gg x^n \\gg \\ln$. Cette hiérarchie tranche les formes indéterminées."},{"kind":"example","title_fr":"Résoudre $e^{2x} - 3 e^x + 2 = 0$","problem_fr":"Trouve les solutions réelles.","steps_fr":["Poser $X = e^x$, $X > 0$. $X^2 - 3X + 2 = 0$, racines $X = 1$ et $X = 2$.","$e^x = 1 \\iff x = 0$ ; $e^x = 2 \\iff x = \\ln 2$."],"answer_fr":"$S = \\{0,\\, \\ln 2\\}$."},{"kind":"checkpoint","title_fr":"Exponentielle","questions":[{"stem_fr":"$e^x \\cdot e^{-x}$ vaut :","choices_fr":["0","1","$e$","$e^{x^2}$"],"correct_index":1,"explanation_fr":"$e^{x-x} = e^0 = 1$."},{"stem_fr":"$\\lim_{x \\to -\\infty} e^x$ vaut :","choices_fr":["$-\\infty$","0","1","$+\\infty$"],"correct_index":1,"explanation_fr":"L''exponentielle tend vers 0 en $-\\infty$."},{"stem_fr":"Dérivée de $x e^x$ :","choices_fr":["$e^x$","$(1+x) e^x$","$e^x/x$","$x^2 e^x$"],"correct_index":1,"explanation_fr":"Produit : $1 \\cdot e^x + x \\cdot e^x = (1+x)e^x$."}]}]}]}'::jsonb WHERE code = 'pc_exp_function';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Primitives","subtitle_fr":"Fonction dont la dérivée est donnée, à constante près.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"3","blocks":[{"kind":"paragraph","md":"$F$ est une **primitive** de $f$ sur $I$ si $F''(x) = f(x)$ pour tout $x \\in I$. Deux primitives diffèrent d''une **constante**."},{"kind":"paragraph","md":"Une condition supplémentaire ($F(x_0) = y_0$) fixe la constante de manière unique."}]},{"kind":"concept","title_fr":"Primitives usuelles et formes reconnaissables","eyebrow_fr":"CATALOGUE","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C \\,(n \\ne -1), \\quad \\int \\frac{1}{x}\\,dx = \\ln|x| + C","caption_fr":"Puissances et inverse."},{"kind":"formula","latex":"\\int e^x\\,dx = e^x + C, \\quad \\int \\sin x\\,dx = -\\cos x + C, \\quad \\int \\cos x\\,dx = \\sin x + C","caption_fr":"Fonctions trigonométriques et exponentielles."},{"kind":"formula","latex":"\\int u''(x) u(x)^n\\,dx = \\frac{u^{n+1}}{n+1} + C, \\quad \\int \\frac{u''}{u}\\,dx = \\ln|u| + C, \\quad \\int u'' e^u\\,dx = e^u + C","caption_fr":"**Formes reconnaissables**."},{"kind":"example","title_fr":"Forme $u''/u$","problem_fr":"Trouver une primitive de $f(x) = 2x/(x^2 + 1)$.","steps_fr":["Reconnaître $u''/u$ avec $u = x^2 + 1$, $u'' = 2x$.","Primitive : $\\ln(x^2 + 1) + C$ (valeur absolue inutile car $u > 0$)."],"answer_fr":"$F(x) = \\ln(x^2 + 1) + C$."},{"kind":"checkpoint","title_fr":"Primitives","questions":[{"stem_fr":"Primitive de $x^3$ :","choices_fr":["$3 x^2$","$x^4/4$","$x^3/3$","$x^2$"],"correct_index":1,"explanation_fr":"$\\int x^n dx = x^{n+1}/(n+1)$."},{"stem_fr":"Primitive de $1/x$ sur $]0, +\\infty[$ :","choices_fr":["$\\ln x$","$1/x^2$","$-1/x^2$","$x$"],"correct_index":0,"explanation_fr":"Primitive de $1/x$ = $\\ln|x|$."},{"stem_fr":"Primitive de $e^{2x}$ :","choices_fr":["$e^{2x}$","$2 e^{2x}$","$e^{2x}/2$","$e^x$"],"correct_index":2,"explanation_fr":"Diviser par 2 pour compenser la dérivation interne."}]}]}]}'::jsonb WHERE code = 'pc_primitives';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Calcul intégral","subtitle_fr":"Intégrale définie, propriétés, aires.","sections":[{"kind":"concept","title_fr":"Définition par primitive","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\int_a^b f(x)\\,dx = F(b) - F(a) \\quad \\text{où } F'' = f","caption_fr":"**Newton-Leibniz** : intégrale = différence de primitives."},{"kind":"paragraph","md":"Géométriquement, $\\int_a^b f$ est l''**aire algébrique** sous la courbe entre $a$ et $b$ (positive au-dessus de l''axe, négative en-dessous)."}]},{"kind":"concept","title_fr":"Propriétés","eyebrow_fr":"PROPRIÉTÉS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\int_a^b (\\alpha f + \\beta g) = \\alpha \\int_a^b f + \\beta \\int_a^b g","caption_fr":"Linéarité."},{"kind":"formula","latex":"\\int_a^c f = \\int_a^b f + \\int_b^c f","caption_fr":"**Relation de Chasles**."},{"kind":"formula","latex":"\\int_a^b f = -\\int_b^a f, \\quad f \\ge 0 \\Rightarrow \\int_a^b f \\ge 0","caption_fr":"Inversion des bornes et positivité."},{"kind":"example","title_fr":"Aire entre deux courbes","problem_fr":"Aire entre $y = x^2$ et $y = x$ sur $[0, 1]$.","steps_fr":["Sur $[0, 1]$, $x \\ge x^2$. Aire $= \\int_0^1 (x - x^2)\\,dx$.","$[x^2/2 - x^3/3]_0^1 = 1/2 - 1/3 = 1/6$."],"answer_fr":"$A = 1/6$."},{"kind":"checkpoint","title_fr":"Calcul intégral","questions":[{"stem_fr":"$\\int_0^1 x^2\\,dx$ vaut :","choices_fr":["1/2","1/3","1/4","1"],"correct_index":1,"explanation_fr":"$[x^3/3]_0^1 = 1/3$."},{"stem_fr":"$\\int_1^e 1/x\\,dx$ vaut :","choices_fr":["0","1","$e$","$e - 1$"],"correct_index":1,"explanation_fr":"$[\\ln x]_1^e = 1 - 0 = 1$."},{"stem_fr":"Si $\\int_0^3 f = 7$ et $\\int_3^5 f = 2$ alors $\\int_0^5 f$ vaut :","choices_fr":["5","7","9","14"],"correct_index":2,"explanation_fr":"Chasles : 7 + 2 = 9."}]}]}]}'::jsonb WHERE code = 'pc_integral_calc';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Nombres complexes — forme algébrique","subtitle_fr":"Définition, opérations, conjugué, module.","sections":[{"kind":"concept","title_fr":"Forme algébrique","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Un nombre complexe s''écrit $z = a + bi$ avec $a, b \\in \\mathbb{R}$ et $i^2 = -1$. $a$ est la **partie réelle**, $b$ la **partie imaginaire**."},{"kind":"formula","latex":"z + z'' = (a + a'') + (b + b'')i, \\quad z \\cdot z'' = (aa'' - bb'') + (ab'' + a''b)i","caption_fr":"Opérations."},{"kind":"formula","latex":"\\bar z = a - bi, \\quad |z| = \\sqrt{a^2 + b^2}, \\quad z \\bar z = |z|^2","caption_fr":"Conjugué, module, identité fondamentale."}]},{"kind":"concept","title_fr":"Inverse et équations","eyebrow_fr":"TECHNIQUES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Pour calculer $1/z$ ou $z''/z$ : **multiplier par le conjugué** du dénominateur pour rendre celui-ci réel."},{"kind":"formula","latex":"\\frac{1}{z} = \\frac{\\bar z}{|z|^2}, \\quad \\frac{z''}{z} = \\frac{z'' \\bar z}{|z|^2}","caption_fr":"Formules."},{"kind":"paragraph","md":"**Équation du 2nd degré** à coefficients réels : si $\\Delta < 0$, deux racines complexes conjuguées $z = (-b \\pm i\\sqrt{-\\Delta})/(2a)$."},{"kind":"example","title_fr":"Équation $z^2 + 4z + 13 = 0$","problem_fr":"Résoudre dans $\\mathbb{C}$.","steps_fr":["$\\Delta = 16 - 52 = -36$. $\\sqrt{-\\Delta} = 6i$.","$z = (-4 \\pm 6i)/2 = -2 \\pm 3i$."],"answer_fr":"$S = \\{-2 + 3i, -2 - 3i\\}$."},{"kind":"checkpoint","title_fr":"Complexes (algèbre)","questions":[{"stem_fr":"$i^2$ vaut :","choices_fr":["0","1","-1","$i$"],"correct_index":2,"explanation_fr":"Définition de $i$."},{"stem_fr":"Module de $3 + 4i$ :","choices_fr":["3","4","5","7"],"correct_index":2,"explanation_fr":"$\\sqrt{9 + 16} = 5$."},{"stem_fr":"Conjugué de $2 - 3i$ :","choices_fr":["$2 + 3i$","$-2 + 3i$","$3 + 2i$","$-2 - 3i$"],"correct_index":0,"explanation_fr":"On change le signe de la partie imaginaire."}]}]}]}'::jsonb WHERE code = 'pc_complex_algebra';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Forme trigonométrique et formule de Moivre","subtitle_fr":"Exponentielle complexe, racines n-ièmes.","sections":[{"kind":"concept","title_fr":"Forme exponentielle","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"z = r(\\cos\\theta + i \\sin\\theta) = r e^{i\\theta}, \\quad r = |z|, \\quad \\theta = \\arg z","caption_fr":"Module-argument, et notation exponentielle."},{"kind":"paragraph","md":"Pour passer de $z = a + bi$ à la forme exp : calculer $r = |z|$, puis $\\theta$ via $\\cos\\theta = a/r$ et $\\sin\\theta = b/r$ (les deux pour lever l''ambiguïté)."},{"kind":"callout","tone":"insight","title_fr":"Identité d''Euler","body_fr":"$e^{i\\pi} + 1 = 0$ relie 5 constantes fondamentales ($e, i, \\pi, 1, 0$)."}]},{"kind":"concept","title_fr":"Moivre et racines n-ièmes","eyebrow_fr":"OUTILS","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"(r e^{i\\theta})^n = r^n e^{i n \\theta}","caption_fr":"**Formule de Moivre** — élève au rang $n$."},{"kind":"paragraph","md":"Les racines n-ièmes d''un complexe $z_0 = r_0 e^{i\\theta_0}$ sont $z_k = r_0^{1/n} e^{i(\\theta_0 + 2k\\pi)/n}$ pour $k = 0, 1, \\dots, n-1$. Géométriquement : sommets d''un polygone régulier."},{"kind":"example","title_fr":"Racines cubiques de l''unité","problem_fr":"Résoudre $z^3 = 1$.","steps_fr":["$1 = e^{i \\cdot 0}$. Racines : $z_k = e^{i 2k\\pi/3}$, $k = 0, 1, 2$.","$z_0 = 1$, $z_1 = -1/2 + i\\sqrt 3/2$, $z_2 = -1/2 - i\\sqrt 3/2$. Triangle équilatéral."],"answer_fr":"3 racines (1 et deux conjuguées)."},{"kind":"checkpoint","title_fr":"Forme trigonométrique","questions":[{"stem_fr":"$|e^{i\\theta}|$ vaut :","choices_fr":["0","1","$\\theta$","$e^\\theta$"],"correct_index":1,"explanation_fr":"Module 1 sur le cercle unité."},{"stem_fr":"$(1+i)^2$ vaut :","choices_fr":["0","$2i$","$1 + 2i$","$2 + i$"],"correct_index":1,"explanation_fr":"Développer : $1 + 2i + i^2 = 2i$."},{"stem_fr":"Nombre de racines n-ièmes d''un complexe non nul :","choices_fr":["1","2","$n$","infinité"],"correct_index":2,"explanation_fr":"$n$ racines distinctes sur le cercle."}]}]}]}'::jsonb WHERE code = 'pc_complex_trig';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Équations différentielles du 1er ordre","subtitle_fr":"$y'' = ay$ et $y'' = ay + b$.","sections":[{"kind":"concept","title_fr":"EDO homogène","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"y'' = a y \\Rightarrow y(x) = C e^{a x}, \\quad C \\in \\mathbb{R}","caption_fr":"**Solution générale**. Une condition initiale $y(x_0) = y_0$ fixe $C$."},{"kind":"paragraph","md":"Modélise : croissance/décroissance exponentielle (population, radioactivité, intérêts composés)."}]},{"kind":"concept","title_fr":"EDO avec second membre","eyebrow_fr":"PRINCIPE","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"y'' = a y + b \\Rightarrow y(x) = C e^{a x} + y_p, \\quad y_p = -b/a","caption_fr":"**Superposition** : solution = homogène + particulière constante."},{"kind":"paragraph","md":"La solution tend vers $y_p$ quand $x \\to +\\infty$ (si $a < 0$) — c''est l''**équilibre**."},{"kind":"example","title_fr":"Refroidissement","problem_fr":"$T''(t) = -k(T - T_0)$ avec $T(0) = T_i$. Solution ?","steps_fr":["Poser $\\theta = T - T_0$. Alors $\\theta'' = -k\\theta$ (homogène).","Solution : $\\theta(t) = (T_i - T_0) e^{-k t}$, donc $T(t) = T_0 + (T_i - T_0) e^{-k t}$."],"answer_fr":"$T \\to T_0$ exponentiellement."},{"kind":"checkpoint","title_fr":"EDO 1er ordre","questions":[{"stem_fr":"Solution de $y'' = 3y$ avec $y(0) = 2$ :","choices_fr":["$3 e^{2x}$","$2 e^{3x}$","$2 + 3x$","$2 e^{-3x}$"],"correct_index":1,"explanation_fr":"$y = C e^{3x}$, CI : $C = 2$."},{"stem_fr":"Pour $y'' = -2y + 10$, solution particulière constante :","choices_fr":["0","2","5","10"],"correct_index":2,"explanation_fr":"$y_p = -10/(-2) = 5$."},{"stem_fr":"Demi-vie d''une décroissance $y'' = -\\lambda y$ :","choices_fr":["$1/\\lambda$","$\\ln 2/\\lambda$","$\\lambda \\ln 2$","$2\\lambda$"],"correct_index":1,"explanation_fr":"$y_0/2 = y_0 e^{-\\lambda t} \\iff t = \\ln 2/\\lambda$."}]}]}]}'::jsonb WHERE code = 'pc_ode_first_order';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Loi binomiale","subtitle_fr":"Schéma de Bernoulli, formule, espérance, variance.","sections":[{"kind":"concept","title_fr":"Schéma de Bernoulli","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Un **schéma de Bernoulli** : $n$ essais identiques, indépendants, à 2 issues (succès de proba $p$, échec de proba $1-p$). $X$ = nombre de succès."},{"kind":"formula","latex":"X \\sim \\mathcal B(n, p) \\Rightarrow P(X = k) = \\binom{n}{k} p^k (1-p)^{n-k}","caption_fr":"Loi binomiale."},{"kind":"formula","latex":"E(X) = n p, \\quad V(X) = n p (1-p), \\quad \\sigma = \\sqrt{V(X)}","caption_fr":"Espérance et variance."}]},{"kind":"example_walkthrough","title_fr":"Exemple QCM","eyebrow_fr":"EXEMPLE","estimated_minutes":"4","blocks":[{"kind":"example","title_fr":"QCM aléatoire","problem_fr":"20 questions, 4 réponses dont 1 correcte, réponses au hasard. Espérance du score ?","steps_fr":["Modèle : $X \\sim \\mathcal B(20, 1/4)$ (chaque question = Bernoulli indépendant).","$E(X) = np = 20 \\times 0{,}25 = 5$. $\\sigma = \\sqrt{20 \\times 0{,}25 \\times 0{,}75} \\approx 1{,}94$.","Score moyen attendu : 5/20, écart-type ~2 → typiquement entre 3 et 7."],"answer_fr":"$E = 5$, $\\sigma \\approx 1{,}94$."},{"kind":"checkpoint","title_fr":"Loi binomiale","questions":[{"stem_fr":"$E(X)$ pour $X \\sim \\mathcal B(10, 0{,}3)$ :","choices_fr":["1","3","7","30"],"correct_index":1,"explanation_fr":"$E = np = 3$."},{"stem_fr":"$P(X = 0)$ pour $X \\sim \\mathcal B(n, p)$ :","choices_fr":["$p$","$(1-p)^n$","$n p$","0"],"correct_index":1,"explanation_fr":"$\\binom{n}{0} p^0 (1-p)^n = (1-p)^n$."},{"stem_fr":"Variance de $\\mathcal B(n, p)$ :","choices_fr":["$np$","$n p (1-p)$","$p (1-p)$","$n^2 p$"],"correct_index":1,"explanation_fr":"Formule binomiale."}]}]}]}'::jsonb WHERE code = 'pc_prob_binomial';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Lois de Newton","subtitle_fr":"Inertie, $\\vec F = m\\vec a$, action-réaction.","sections":[{"kind":"concept","title_fr":"Les trois lois","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**1ère loi (inertie)** : un point matériel isolé est en mouvement rectiligne uniforme (ou au repos). Référentiel galiléen requis."},{"kind":"formula","latex":"\\sum \\vec F_\\text{ext} = m \\vec a","caption_fr":"**2ème loi** : la somme des forces extérieures = masse × accélération."},{"kind":"paragraph","md":"**3ème loi (action-réaction)** : si A exerce $\\vec F$ sur B, alors B exerce $-\\vec F$ sur A (mêmes droite, mêmes intensités, sens opposés)."}]},{"kind":"concept","title_fr":"Applications","eyebrow_fr":"CAS CLASSIQUES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Équilibre statique** : $\\sum \\vec F = \\vec 0$. On projette sur les axes."},{"kind":"paragraph","md":"**Plan incliné** : composante du poids $mg \\sin\\alpha$ tire le bloc vers le bas. Critère de glissement : $\\tan\\alpha > \\mu_s$."},{"kind":"paragraph","md":"**Mouvement circulaire uniforme** : force centripète $F = m v^2 / r$ vers le centre."},{"kind":"example","title_fr":"Plan incliné sans frottement","problem_fr":"Bloc 10 kg sur plan à 30°, $g = 10\\,\\text{m/s}^2$. Accélération ?","steps_fr":["Forces : poids et réaction normale. Selon le plan : $m a = m g \\sin\\alpha$.","$a = g \\sin 30° = 10 \\times 0{,}5 = 5\\,\\text{m/s}^2$."],"answer_fr":"$a = 5\\,\\text{m/s}^2$."},{"kind":"checkpoint","title_fr":"Newton","questions":[{"stem_fr":"Unité de la force :","choices_fr":["$\\text{kg/m}$","$\\text{N} = \\text{kg}\\cdot\\text{m/s}^2$","$\\text{J}$","$\\text{W}$"],"correct_index":1,"explanation_fr":"Définition : $F = m a$ donne kg·m/s² = N."},{"stem_fr":"Si $\\sum \\vec F = \\vec 0$, l''objet :","choices_fr":["accélère","est au repos ou MRU","tourne","tombe"],"correct_index":1,"explanation_fr":"Première loi de Newton."},{"stem_fr":"Force centripète à vitesse $v$, rayon $r$, masse $m$ :","choices_fr":["$m v r$","$m v^2/r$","$m v/r$","$m r/v^2$"],"correct_index":1,"explanation_fr":"$F_c = m v^2/r$ vers le centre."}]}]}]}'::jsonb WHERE code = 'pc_newton_laws';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Mouvement d''un projectile","subtitle_fr":"Chute libre, tir parabolique.","sections":[{"kind":"concept","title_fr":"Équations horaires","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un projectile soumis à la seule gravité a deux composantes **indépendantes** : horizontale (MRU) et verticale (MRUA avec accélération $-g$)."},{"kind":"formula","latex":"x(t) = v_0 \\cos\\alpha \\cdot t, \\quad y(t) = v_0 \\sin\\alpha \\cdot t - \\frac{1}{2} g t^2","caption_fr":"Équations horaires."},{"kind":"formula","latex":"y(x) = x \\tan\\alpha - \\frac{g x^2}{2 v_0^2 \\cos^2\\alpha}","caption_fr":"Équation cartésienne : **parabole**."}]},{"kind":"concept","title_fr":"Portée et hauteur","eyebrow_fr":"FORMULES","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"x_p = \\frac{v_0^2 \\sin(2\\alpha)}{g}, \\quad h_\\text{max} = \\frac{v_0^2 \\sin^2\\alpha}{2g}","caption_fr":"Portée et hauteur maximale."},{"kind":"callout","tone":"insight","title_fr":"Portée maximale","body_fr":"Pour $v_0$ donnée, la portée est max quand $\\sin(2\\alpha) = 1 \\iff \\alpha = 45°$. Au-delà ou en deçà, elle diminue symétriquement."},{"kind":"example","title_fr":"Chute libre","problem_fr":"Pierre lâchée d''une falaise. Touche le sol après 3 s. Hauteur ? (g = 10)","steps_fr":["Chute libre : $h = (1/2) g t^2 = 0{,}5 \\times 10 \\times 9 = 45\\,\\text{m}$.","Vitesse à l''impact : $v = g t = 30\\,\\text{m/s}$."],"answer_fr":"$h = 45$ m."},{"kind":"checkpoint","title_fr":"Projectile","questions":[{"stem_fr":"Angle de portée maximale dans le vide :","choices_fr":["30°","45°","60°","90°"],"correct_index":1,"explanation_fr":"$\\sin(2\\alpha)$ max pour $\\alpha = 45°$."},{"stem_fr":"Composante horizontale d''un tir à $v_0$, angle $\\alpha$ :","choices_fr":["$v_0$","$v_0 \\sin\\alpha$","$v_0 \\cos\\alpha$","$g t$"],"correct_index":2,"explanation_fr":"Projection horizontale."},{"stem_fr":"Hauteur après chute de 2 s (g=10) :","choices_fr":["10 m","20 m","40 m","100 m"],"correct_index":1,"explanation_fr":"$h = 0{,}5 \\times 10 \\times 4 = 20$."}]}]}]}'::jsonb WHERE code = 'pc_projectile';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Énergie mécanique","subtitle_fr":"Cinétique, potentielle, conservation.","sections":[{"kind":"concept","title_fr":"Formes d''énergie","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"E_c = \\frac{1}{2} m v^2, \\quad E_p = m g h, \\quad E_{pe} = \\frac{1}{2} k x^2","caption_fr":"Cinétique, potentielle pesanteur, potentielle élastique."},{"kind":"formula","latex":"E_m = E_c + E_p","caption_fr":"**Énergie mécanique** = somme des deux."}]},{"kind":"concept","title_fr":"Conservation et TEC","eyebrow_fr":"LOIS","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Sans frottement** : $E_m$ est conservée. Avec frottements : $\\Delta E_m = W_\\text{frot} < 0$."},{"kind":"formula","latex":"\\Delta E_c = \\sum W_\\text{ext}","caption_fr":"**Théorème de l''énergie cinétique** : la variation d''$E_c$ = somme des travaux."},{"kind":"example","title_fr":"Toboggan sans frottement","problem_fr":"Enfant lâché du haut d''un toboggan de 4 m. Vitesse en bas ? (g=10)","steps_fr":["Conservation : $m g h = (1/2) m v^2 \\Rightarrow v = \\sqrt{2 g h}$.","$v = \\sqrt{80} \\approx 8{,}94\\,\\text{m/s}$. Indépendant de la masse !"],"answer_fr":"$\\approx 8{,}94$ m/s."},{"kind":"checkpoint","title_fr":"Énergie","questions":[{"stem_fr":"$E_c$ d''un objet 2 kg à 10 m/s :","choices_fr":["10 J","50 J","100 J","200 J"],"correct_index":2,"explanation_fr":"$(1/2)(2)(100) = 100$ J."},{"stem_fr":"Sans frottement, $E_m$ :","choices_fr":["augmente","décroît","est constante","tend vers 0"],"correct_index":2,"explanation_fr":"Conservation."},{"stem_fr":"Théorème de l''énergie cinétique :","choices_fr":["$\\Delta E_c = m g h$","$\\Delta E_c = \\sum W$","$\\Delta E_c = 0$","$E_c = E_p$"],"correct_index":1,"explanation_fr":"Variation d''$E_c$ = somme des travaux."}]}]}]}'::jsonb WHERE code = 'pc_energy_mechanical';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Pendule pesant et élastique","subtitle_fr":"Oscillateur harmonique, période propre.","sections":[{"kind":"concept","title_fr":"Pendule simple","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une masse au bout d''un fil de longueur $L$, écartée d''un petit angle $\\theta_0$ et lâchée, oscille."},{"kind":"formula","latex":"\\theta'''' + \\frac{g}{L} \\theta = 0 \\quad (\\text{petits angles})","caption_fr":"Équation différentielle (approximation $\\sin\\theta \\approx \\theta$)."},{"kind":"formula","latex":"T_0 = 2\\pi \\sqrt{L/g}","caption_fr":"**Période** — indépendante de l''amplitude (isochronisme) et de la masse."}]},{"kind":"concept","title_fr":"Pendule élastique (ressort-masse)","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"x'''' + \\frac{k}{m} x = 0 \\Rightarrow T_0 = 2\\pi \\sqrt{m/k}","caption_fr":"Équation et période."},{"kind":"formula","latex":"\\omega_0 = \\sqrt{k/m} \\text{ (élastique) ou } \\sqrt{g/L} \\text{ (simple)}","caption_fr":"Pulsation propre."},{"kind":"example","title_fr":"Période d''un pendule simple","problem_fr":"Longueur $L = 1\\,\\text{m}$, $g = 9{,}81\\,\\text{m/s}^2$. Période ?","steps_fr":["$T_0 = 2\\pi \\sqrt{1/9{,}81} \\approx 2{,}01\\,\\text{s}$.","Un pendule de 1 m bat la seconde (aller-retour ≈ 2 s)."],"answer_fr":"$T_0 \\approx 2\\,\\text{s}$."},{"kind":"checkpoint","title_fr":"Pendule","questions":[{"stem_fr":"Période d''un pendule simple $L$, $g$ :","choices_fr":["$\\sqrt{L/g}$","$2\\pi \\sqrt{L/g}$","$2\\pi L/g$","$L g$"],"correct_index":1,"explanation_fr":"Formule fondamentale."},{"stem_fr":"La période dépend-elle de la masse pour un pendule simple ?","choices_fr":["oui","non","parfois","selon l''angle"],"correct_index":1,"explanation_fr":"La masse se simplifie dans l''équation."},{"stem_fr":"Pulsation propre d''un ressort $k, m$ :","choices_fr":["$k/m$","$\\sqrt{m/k}$","$\\sqrt{k/m}$","$k m$"],"correct_index":2,"explanation_fr":"$\\omega_0 = \\sqrt{k/m}$."}]}]}]}'::jsonb WHERE code = 'pc_pendulum';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Dipôle RC","subtitle_fr":"Charge et décharge d''un condensateur.","sections":[{"kind":"concept","title_fr":"Charge","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Quand on ferme un interrupteur dans un circuit $E, R, C$, le condensateur se charge progressivement ($u_C$ augmente)."},{"kind":"formula","latex":"\\tau \\frac{du_C}{dt} + u_C = E, \\quad u_C(t) = E (1 - e^{-t/\\tau}), \\quad \\tau = R C","caption_fr":"EDO et solution. $\\tau$ = **constante de temps**."},{"kind":"callout","tone":"insight","title_fr":"Règle du 5τ","body_fr":"À $t = 3\\tau$, $u_C \\approx 95\\%\\,E$ ; à $5\\tau$, plus de 99% — régime considéré établi."}]},{"kind":"concept","title_fr":"Décharge et énergie","eyebrow_fr":"DÉCHARGE","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"u_C(t) = U_0 e^{-t/\\tau}","caption_fr":"Décharge : exponentielle décroissante."},{"kind":"formula","latex":"E_C = \\frac{1}{2} C u_C^2","caption_fr":"Énergie stockée dans le condensateur."},{"kind":"example","title_fr":"Charge d''un condensateur","problem_fr":"$E = 12\\,\\text{V}$, $R = 1\\,\\text{k}\\Omega$, $C = 100\\,\\mu\\text{F}$. Calculer $\\tau$.","steps_fr":["$\\tau = RC = 10^3 \\times 10^{-4} = 0{,}1\\,\\text{s} = 100\\,\\text{ms}$.","Régime établi vers $5\\tau = 500\\,\\text{ms}$."],"answer_fr":"$\\tau = 100\\,\\text{ms}$."},{"kind":"checkpoint","title_fr":"Dipôle RC","questions":[{"stem_fr":"Constante de temps RC :","choices_fr":["$R + C$","$R/C$","$R C$","$1/(R C)$"],"correct_index":2,"explanation_fr":"$\\tau = R C$ (dimensions s)."},{"stem_fr":"À $t = \\tau$, $u_C$ vaut :","choices_fr":["$E/e$","$E(1 - 1/e)\\approx 0{,}63 E$","$E$","$E/2$"],"correct_index":1,"explanation_fr":"$u_C(\\tau) = E(1 - e^{-1})$."},{"stem_fr":"Énergie d''un condensateur chargé à $U$ :","choices_fr":["$C U$","$C U^2$","$(1/2) C U^2$","$U/C$"],"correct_index":2,"explanation_fr":"$E = \\frac{1}{2} C U^2$."}]}]}]}'::jsonb WHERE code = 'pc_rc_circuit';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Dipôle RL","subtitle_fr":"Bobine, établissement et rupture du courant.","sections":[{"kind":"concept","title_fr":"Établissement du courant","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une bobine s''oppose aux variations rapides de courant — elle réagit comme un ''volant d''inertie'' électrique."},{"kind":"formula","latex":"L \\frac{di}{dt} + R i = E, \\quad i(t) = \\frac{E}{R}(1 - e^{-t/\\tau}), \\quad \\tau = L/R","caption_fr":"EDO et solution."},{"kind":"formula","latex":"u_L = L \\frac{di}{dt} = E e^{-t/\\tau}","caption_fr":"Tension aux bornes de la bobine — max à $t=0$, nulle à l''infini."}]},{"kind":"concept","title_fr":"Énergie et symétrie avec RC","eyebrow_fr":"ANALOGIES","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"E_L = \\frac{1}{2} L i^2","caption_fr":"Énergie magnétique stockée."},{"kind":"paragraph","md":"Analogie complète RC ↔ RL : $u_C$ joue le rôle de $i$, $Q$ joue celui de $\\Phi$ (flux magnétique). Mêmes formes d''équations, mêmes comportements transitoires."},{"kind":"checkpoint","title_fr":"Dipôle RL","questions":[{"stem_fr":"Constante de temps RL :","choices_fr":["$R/L$","$L R$","$L/R$","$1/(L R)$"],"correct_index":2,"explanation_fr":"$\\tau = L/R$."},{"stem_fr":"À $t = 0$ (fermeture), $u_L$ vaut :","choices_fr":["0","$E$","$E/2$","$\\infty$"],"correct_index":1,"explanation_fr":"La bobine absorbe toute la tension initialement."},{"stem_fr":"Énergie magnétique d''une bobine parcourue par $I$ :","choices_fr":["$L I$","$L I^2$","$(1/2) L I^2$","$I/L$"],"correct_index":2,"explanation_fr":"$E_L = \\frac{1}{2} L i^2$."}]}]}]}'::jsonb WHERE code = 'pc_rl_circuit';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Oscillations RLC libres","subtitle_fr":"LC idéal, trois régimes, pulsation propre.","sections":[{"kind":"concept","title_fr":"Circuit LC idéal","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"L \\ddot u_C + \\frac{1}{C} q = 0 \\Rightarrow u_C'''' + \\omega_0^2 u_C = 0, \\quad \\omega_0 = \\frac{1}{\\sqrt{LC}}","caption_fr":"Équation et pulsation propre."},{"kind":"paragraph","md":"Solution sinusoïdale : oscillations harmoniques non amorties. L''énergie échange continuellement entre le condensateur (électrique) et la bobine (magnétique)."},{"kind":"formula","latex":"T_0 = 2\\pi \\sqrt{LC}","caption_fr":"Période propre."}]},{"kind":"concept","title_fr":"RLC réel — trois régimes","eyebrow_fr":"RÉGIMES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Avec une résistance $R$, l''amplitude décroît exponentiellement. Trois cas selon $R$ vs résistance critique $R_c = 2\\sqrt{L/C}$ :"},{"kind":"paragraph","md":"- **Pseudo-périodique** ($R < R_c$) : oscillations amorties."},{"kind":"paragraph","md":"- **Critique** ($R = R_c$) : retour le plus rapide sans oscillation."},{"kind":"paragraph","md":"- **Apériodique** ($R > R_c$) : retour lent sans oscillation."},{"kind":"checkpoint","title_fr":"RLC","questions":[{"stem_fr":"Pulsation propre LC :","choices_fr":["$L C$","$\\sqrt{LC}$","$1/\\sqrt{LC}$","$1/(LC)$"],"correct_index":2,"explanation_fr":"$\\omega_0 = 1/\\sqrt{LC}$."},{"stem_fr":"Résistance critique :","choices_fr":["$\\sqrt{L C}$","$2 \\sqrt{L/C}$","$L/C$","$L C / 2$"],"correct_index":1,"explanation_fr":"$R_c = 2\\sqrt{L/C}$."},{"stem_fr":"Pour $R < R_c$, le régime est :","choices_fr":["pseudo-périodique","critique","apériodique","instable"],"correct_index":0,"explanation_fr":"Oscillations amorties."}]}]}]}'::jsonb WHERE code = 'pc_rlc_oscillations';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Ondes mécaniques","subtitle_fr":"Célérité, longueur d''onde, types d''ondes.","sections":[{"kind":"concept","title_fr":"Définition et grandeurs","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une **onde mécanique** est la propagation d''une perturbation dans un milieu matériel **sans transport de matière**. Seule l''énergie se propage."},{"kind":"formula","latex":"\\lambda = v T = v/f","caption_fr":"Relation fondamentale entre **longueur d''onde**, célérité et fréquence."},{"kind":"paragraph","md":"**Transversale** : oscillation perpendiculaire à la direction (ex. corde). **Longitudinale** : parallèle (ex. son)."}]},{"kind":"concept","title_fr":"Retard et déphasage","eyebrow_fr":"PROPRIÉTÉS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\tau = d/v, \\quad \\Delta\\varphi = 2\\pi f \\tau = 2\\pi d/\\lambda","caption_fr":"**Retard** temporel et **déphasage** spatial."},{"kind":"paragraph","md":"Deux points sont **en phase** si $d = n\\lambda$ (n entier), en **opposition** de phase si $d = (n + 1/2)\\lambda$."},{"kind":"checkpoint","title_fr":"Ondes","questions":[{"stem_fr":"Relation $\\lambda, v, f$ :","choices_fr":["$\\lambda = v f$","$\\lambda = v/f$","$\\lambda = f/v$","$\\lambda = v + f$"],"correct_index":1,"explanation_fr":"$\\lambda = v T = v/f$."},{"stem_fr":"Le son est :","choices_fr":["transversal","longitudinal","les deux","aucun"],"correct_index":1,"explanation_fr":"Compressions/raréfactions dans la direction du son."},{"stem_fr":"Célérité du son dans l''air (20°C) :","choices_fr":["30 m/s","340 m/s","3000 m/s","300000 km/s"],"correct_index":1,"explanation_fr":"Valeur classique à connaître."}]}]}]}'::jsonb WHERE code = 'pc_mechanical_waves';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Diffraction et interférences","subtitle_fr":"Comportement ondulatoire de la lumière.","sections":[{"kind":"concept","title_fr":"Diffraction","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"La **diffraction** est l''étalement d''une onde traversant une ouverture (ou contournant un obstacle) de taille comparable à $\\lambda$."},{"kind":"formula","latex":"\\theta \\approx \\lambda/a","caption_fr":"Demi-angle d''ouverture pour une fente de largeur $a$."},{"kind":"callout","tone":"insight","title_fr":"Plus la fente est étroite, plus la tache est large","body_fr":"Contre-intuitif mais essentiel — c''est pourquoi les objectifs photo doivent avoir une grande ouverture pour être nets."}]},{"kind":"concept","title_fr":"Interférences (Young)","eyebrow_fr":"INTERFÉRENCES","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"i = \\lambda D / a","caption_fr":"**Interfrange** : distance entre deux franges brillantes dans le dispositif de Young ($D$ distance fentes-écran, $a$ écart entre fentes)."},{"kind":"paragraph","md":"Conditions : sources **cohérentes** (même longueur d''onde, déphasage constant). En pratique : une source unique séparée en deux."},{"kind":"checkpoint","title_fr":"Diffraction et interférences","questions":[{"stem_fr":"Pour observer la diffraction, la fente doit être :","choices_fr":["$a \\gg \\lambda$","$a \\approx \\lambda$","$a = 0$","infinie"],"correct_index":1,"explanation_fr":"Diffraction notable quand $a \\sim \\lambda$."},{"stem_fr":"Interfrange $i = \\lambda D / a$. Si on augmente $\\lambda$ :","choices_fr":["i diminue","i augmente","i constant","i s''annule"],"correct_index":1,"explanation_fr":"$i \\propto \\lambda$."},{"stem_fr":"Les interférences exigent des sources :","choices_fr":["différentes","incohérentes","cohérentes","lumineuses"],"correct_index":2,"explanation_fr":"Cohérence (même $\\lambda$, déphasage constant)."}]}]}]}'::jsonb WHERE code = 'pc_diffraction_interference';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Modulation d''amplitude (AM)","subtitle_fr":"Porteuse, signal informatif, démodulation par enveloppe.","sections":[{"kind":"concept","title_fr":"Principe","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"La radio AM module l''**amplitude** d''une porteuse haute fréquence $f_p$ par un signal basse fréquence $s(t)$ (voix, musique)."},{"kind":"formula","latex":"u(t) = [A + s(t)] \\cos(2\\pi f_p t)","caption_fr":"Signal modulé : enveloppe $A + s(t)$, porteuse $\\cos(\\dots)$."},{"kind":"formula","latex":"m = S_\\text{max}/A < 1","caption_fr":"**Taux de modulation**. Si $m > 1$ : surmodulation → distorsion."}]},{"kind":"concept","title_fr":"Démodulation par détection d''enveloppe","eyebrow_fr":"CIRCUIT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un démodulateur AM = **diode** (redresse) + **RC passe-bas** (lisse). Condition sur $\\tau = RC$ :"},{"kind":"formula","latex":"T_p \\ll \\tau \\ll T_s","caption_fr":"Où $T_p$ = période porteuse, $T_s$ = période signal."},{"kind":"callout","tone":"warning","title_fr":"Choix de $\\tau$","body_fr":"Si $\\tau$ trop petit : ondulation HF résiduelle. Si trop grand : enveloppe lissée et perdue."},{"kind":"checkpoint","title_fr":"AM","questions":[{"stem_fr":"Pour une bonne modulation, $m$ doit être :","choices_fr":["< 0","< 1","> 1","= 1"],"correct_index":1,"explanation_fr":"Sinon surmodulation."},{"stem_fr":"Le démodulateur AM contient :","choices_fr":["une bobine","une diode + RC","un transformateur","un transistor seul"],"correct_index":1,"explanation_fr":"Détection d''enveloppe = diode + filtre RC."},{"stem_fr":"Si $f_p = 100\\,\\text{kHz}$ et $f_s = 1\\,\\text{kHz}$, $\\tau$ raisonnable :","choices_fr":["1 ns","10 µs à 100 µs","1 s","1 ms"],"correct_index":1,"explanation_fr":"Entre $T_p = 10\\,\\mu s$ et $T_s = 1\\,ms$."}]}]}]}'::jsonb WHERE code = 'pc_am_modulation';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Radioactivité","subtitle_fr":"Désintégrations, loi de décroissance, demi-vie.","sections":[{"kind":"concept","title_fr":"Types de désintégrations","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Un noyau $^A_Z X$ instable se désintègre spontanément. Lois de conservation : $A$ et $Z$ totaux conservés."},{"kind":"formula","latex":"\\alpha : \\,^A_Z X \\to \\,^{A-4}_{Z-2} Y + \\,^4_2 \\text{He}","caption_fr":"Émission d''un noyau d''hélium."},{"kind":"formula","latex":"\\beta^- : \\,^A_Z X \\to \\,^A_{Z+1} Y + \\,^0_{-1} e","caption_fr":"Un neutron → proton + électron."},{"kind":"formula","latex":"\\beta^+ : \\,^A_Z X \\to \\,^A_{Z-1} Y + \\,^0_{+1} e","caption_fr":"Un proton → neutron + positron."}]},{"kind":"concept","title_fr":"Loi de décroissance","eyebrow_fr":"LOI","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"N(t) = N_0 e^{-\\lambda t}, \\quad A(t) = \\lambda N(t)","caption_fr":"Nombre de noyaux et activité (Bq = désint./s)."},{"kind":"formula","latex":"t_{1/2} = \\frac{\\ln 2}{\\lambda}","caption_fr":"**Demi-vie** : temps pour que $N$ soit divisée par 2."},{"kind":"example","title_fr":"Datation au C14","problem_fr":"Un échantillon contient 25% de l''activité d''origine. Âge ? (t½ = 5730 ans)","steps_fr":["$A/A_0 = 1/4 = 1/2^2$ → 2 demi-vies se sont écoulées.","Âge = $2 \\times 5730 = 11\\,460\\,\\text{ans}$."],"answer_fr":"≈ 11 460 ans."},{"kind":"checkpoint","title_fr":"Radioactivité","questions":[{"stem_fr":"Émission $\\alpha$ = particule $^4_2\\text{He}$. Conservation :","choices_fr":["A et Z séparément","A seulement","Z seulement","ni A ni Z"],"correct_index":0,"explanation_fr":"Lois de Soddy."},{"stem_fr":"Demi-vie en fonction de $\\lambda$ :","choices_fr":["$1/\\lambda$","$\\ln 2/\\lambda$","$\\lambda \\ln 2$","$2\\lambda$"],"correct_index":1,"explanation_fr":"$t_{1/2} = \\ln 2/\\lambda$."},{"stem_fr":"Après 3 demi-vies, il reste :","choices_fr":["1/3","1/6","1/8","1/9"],"correct_index":2,"explanation_fr":"$N/N_0 = 1/2^3 = 1/8$."}]}]}]}'::jsonb WHERE code = 'pc_radioactivity';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Vitesse de réaction","subtitle_fr":"Cinétique chimique, facteurs, temps de demi-réaction.","sections":[{"kind":"concept","title_fr":"Vitesse et facteurs","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"v = \\frac{1}{V} \\frac{d\\xi}{dt} = -\\frac{1}{\\nu_R} \\frac{d[R]}{dt}","caption_fr":"**Vitesse volumique** de réaction ($\\nu_R$ = coeff stoechio du réactif)."},{"kind":"paragraph","md":"**Facteurs cinétiques** : température (T ↑ → v ↑, règle des 10°C qui doublent v), concentration (plus de chocs), catalyseur (réduit $E_a$), surface (réactifs solides)."}]},{"kind":"concept","title_fr":"Cinétique d''ordre 1","eyebrow_fr":"LOI","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"v = k [R] \\Rightarrow [R](t) = [R]_0 e^{-k t}, \\quad t_{1/2} = \\ln 2/k","caption_fr":"Loi d''ordre 1 — structure identique à la radioactivité."},{"kind":"callout","tone":"insight","title_fr":"$t_{1/2}$ indépendant de $[R]_0$","body_fr":"Pour une réaction d''ordre 1, le temps de demi-réaction est constant. C''est le marqueur expérimental de l''ordre 1."},{"kind":"checkpoint","title_fr":"Vitesse de réaction","questions":[{"stem_fr":"Effet d''augmenter T de 10°C (règle empirique) :","choices_fr":["v constant","v doublé","v divisé","v annulé"],"correct_index":1,"explanation_fr":"Règle de van''t Hoff."},{"stem_fr":"Un catalyseur :","choices_fr":["change l''équilibre","modifie K","baisse $E_a$","consomme le réactif"],"correct_index":2,"explanation_fr":"Diminue l''énergie d''activation."},{"stem_fr":"$t_{1/2}$ pour $k = 0{,}1\\,\\text{s}^{-1}$ (ordre 1) :","choices_fr":["1 s","~7 s","10 s","100 s"],"correct_index":1,"explanation_fr":"$\\ln 2/0{,}1 \\approx 6{,}93\\,\\text{s}$."}]}]}]}'::jsonb WHERE code = 'pc_reaction_speed';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"pH et acides-bases","subtitle_fr":"Définition, acide fort/faible, pKa.","sections":[{"kind":"concept","title_fr":"Définitions et autoprotolyse","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"pH = -\\log[\\text{H}_3\\text{O}^+], \\quad K_e = [\\text{H}_3\\text{O}^+][\\text{OH}^-] = 10^{-14} \\,(25°C)","caption_fr":"Définition du pH et produit ionique de l''eau."},{"kind":"paragraph","md":"Solution **acide** : pH < 7 ($[\\text{H}_3\\text{O}^+] > [\\text{OH}^-]$). Solution **basique** : pH > 7. Neutre : pH = 7."}]},{"kind":"concept","title_fr":"Acides forts et faibles","eyebrow_fr":"CLASSIFICATION","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Acide fort** (HCl, HNO₃) : totalement dissocié → $[\\text{H}_3\\text{O}^+] = C$, $pH = -\\log C$."},{"kind":"paragraph","md":"**Acide faible** (CH₃COOH) : partiellement dissocié. Équilibre régi par $K_a$ (ou pKa = $-\\log K_a$)."},{"kind":"formula","latex":"pH \\approx \\frac{1}{2}(pKa - \\log C_0)","caption_fr":"Formule simplifiée pour un acide faible peu dissocié."},{"kind":"formula","latex":"pH = pKa + \\log\\frac{[A^-]}{[HA]}","caption_fr":"**Henderson-Hasselbalch** — clé des tampons."},{"kind":"checkpoint","title_fr":"pH","questions":[{"stem_fr":"pH d''une solution d''acide fort $C = 0{,}01\\,\\text{mol/L}$ :","choices_fr":["1","2","7","12"],"correct_index":1,"explanation_fr":"$-\\log 0{,}01 = 2$."},{"stem_fr":"À 25°C, pH + pOH vaut :","choices_fr":["7","10","14","$2 \\log 10$"],"correct_index":2,"explanation_fr":"$K_e = 10^{-14}$."},{"stem_fr":"Pour pH = pKa, on a :","choices_fr":["[HA] = [A^-]","[HA] = 0","[A^-] = 0","[HA] = [H_3O^+]"],"correct_index":0,"explanation_fr":"Henderson-Hasselbalch : $\\log 1 = 0$."}]}]}]}'::jsonb WHERE code = 'pc_ph_calculation';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Titrage acide-base","subtitle_fr":"Équivalence, indicateurs, courbe pH-V.","sections":[{"kind":"concept","title_fr":"Équivalence","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"C_a V_a = C_b V_b^\\text{eq}","caption_fr":"À l''équivalence : moles d''acide = moles de base ajoutées (réaction 1:1)."},{"kind":"paragraph","md":"**Avant l''équivalence** : excès d''acide → pH bas. **À l''équivalence** : sel en solution (pH = 7 pour fort+fort, > 7 pour faible+fort). **Après** : excès de base → pH > 7."}]},{"kind":"concept","title_fr":"Indicateurs et exploitation","eyebrow_fr":"PRATIQUE","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Indicateurs courants** : Hélianthine (3,1–4,4), BBT (6,0–7,6), Phénolphtaléine (8,2–10)."},{"kind":"paragraph","md":"**Choix** : la zone de virage doit contenir le pH d''équivalence. Fort+fort → BBT. Faible+fort → phénolphtaléine."},{"kind":"callout","tone":"insight","title_fr":"Demi-équivalence","body_fr":"Pour un acide faible : à $V_b = V_b^\\text{eq}/2$, $[HA] = [A^-]$ → $pH = pKa$. C''est la méthode standard de mesure du pKa."},{"kind":"checkpoint","title_fr":"Titrage","questions":[{"stem_fr":"À l''équivalence d''un titrage fort+fort, pH :","choices_fr":["< 7","= 7","> 7","imprévisible"],"correct_index":1,"explanation_fr":"Sel neutre."},{"stem_fr":"À la demi-équivalence d''un acide faible :","choices_fr":["pH = 7","pH = 0","pH = pKa","pH = -log C"],"correct_index":2,"explanation_fr":"Henderson-Hasselbalch avec $[HA] = [A^-]$."},{"stem_fr":"Indicateur le plus adapté pour HCl + NaOH :","choices_fr":["hélianthine","BBT","phénolphtaléine","aucun"],"correct_index":1,"explanation_fr":"Équivalence à pH = 7 ; BBT (6–7,6) idéal."}]}]}]}'::jsonb WHERE code = 'pc_titration';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Estérification et hydrolyse","subtitle_fr":"Équilibre, déplacement, saponification.","sections":[{"kind":"concept","title_fr":"Réaction et équilibre","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\text{R-COOH} + \\text{R''-OH} \\rightleftharpoons \\text{R-COO-R''} + \\text{H}_2\\text{O}","caption_fr":"Estérification (sens direct) / hydrolyse (sens inverse)."},{"kind":"paragraph","md":"Caractéristiques : **lente**, **limitée** (K ≈ 4), **athermique** ($\\Delta H \\approx 0$ → T ne déplace pas l''équilibre, mais accélère la cinétique)."}]},{"kind":"concept","title_fr":"Déplacement et saponification","eyebrow_fr":"AMÉLIORATIONS","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Déplacer l''équilibre** : excès d''un réactif (Le Chatelier), ou éliminer l''eau par distillation."},{"kind":"paragraph","md":"**Saponification** : ester + base forte → carboxylate + alcool, **totale** (le carboxylate est très stable, K très grand). Procédé industriel pour les savons."},{"kind":"example","title_fr":"Mélange 1+1 mol, K = 4","problem_fr":"Taux d''avancement final ?","steps_fr":["Tableau : $n_a = n_\\text{al} = 1 - \\xi$, $n_e = n_w = \\xi$.","$K = \\xi^2/(1-\\xi)^2 = 4 \\iff \\xi/(1-\\xi) = 2 \\iff \\xi = 2/3$."],"answer_fr":"67% d''avancement."},{"kind":"checkpoint","title_fr":"Estérification","questions":[{"stem_fr":"La réaction d''estérification est :","choices_fr":["rapide et totale","lente et limitée","instantanée","exothermique forte"],"correct_index":1,"explanation_fr":"Caractéristiques principales."},{"stem_fr":"Effet d''augmenter T sur l''équilibre estérification :","choices_fr":["aucun (athermique)","favorise","défavorise","rend totale"],"correct_index":0,"explanation_fr":"$\\Delta H \\approx 0$."},{"stem_fr":"Saponification = ester + :","choices_fr":["eau","acide fort","base forte","alcool"],"correct_index":2,"explanation_fr":"Réaction totale donnant carboxylate."}]}]}]}'::jsonb WHERE code = 'pc_esterification';
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Pile Daniell et oxydoréduction","subtitle_fr":"Demi-équations, fem, quantité de charge.","sections":[{"kind":"concept","title_fr":"Fonctionnement","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Pile Daniell : électrode Zn dans $\\text{ZnSO}_4$, électrode Cu dans $\\text{CuSO}_4$, pont salin."},{"kind":"formula","latex":"\\text{Anode (-) : } \\text{Zn} \\to \\text{Zn}^{2+} + 2 e^-","caption_fr":"Oxydation."},{"kind":"formula","latex":"\\text{Cathode (+) : } \\text{Cu}^{2+} + 2 e^- \\to \\text{Cu}","caption_fr":"Réduction."},{"kind":"formula","latex":"\\text{Bilan : } \\text{Zn} + \\text{Cu}^{2+} \\to \\text{Zn}^{2+} + \\text{Cu}","caption_fr":"Réaction globale ; fem ≈ 1,10 V."}]},{"kind":"concept","title_fr":"Quantité de charge","eyebrow_fr":"CALCULS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"Q = I \\cdot t = n_e \\cdot F, \\quad F \\approx 96\\,500\\,\\text{C/mol}","caption_fr":"**Constante de Faraday**."},{"kind":"paragraph","md":"Le **pont salin** maintient l''électroneutralité : cations migrent vers la cathode, anions vers l''anode. Sans pont, la pile ne fonctionne pas."},{"kind":"checkpoint","title_fr":"Pile Daniell","questions":[{"stem_fr":"À l''anode d''une pile :","choices_fr":["réduction","oxydation","rien","le métal se dépose"],"correct_index":1,"explanation_fr":"L''anode est le siège de l''oxydation (mnémonique : An-Ox)."},{"stem_fr":"fem théorique de la pile Daniell :","choices_fr":["0,1 V","1,1 V","11 V","110 V"],"correct_index":1,"explanation_fr":"$E° = 0{,}34 - (-0{,}76) = 1{,}10\\,\\text{V}$."},{"stem_fr":"Charge écoulée pour 1 mol d''électrons :","choices_fr":["96 500 C","1 C","1 A","96 500 J"],"correct_index":0,"explanation_fr":"Constante de Faraday."}]}]}]}'::jsonb WHERE code = 'pc_daniell_cell';

COMMIT;
